// F005-AC-02 (TC-UI-001): the four output formats from a token fixture (inline snapshots) and the full set of
// generated files with GENERATED markers. Godot .tres files are validated structurally (Godot is not run here).
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { formatCssVars } from './css-vars.mjs';
import { formatAntdTheme } from './antd-theme.mjs';
import { gdConst, formatUiTokens } from './gdscript-tokens.mjs';
import { formatGodotJson } from './godot-json.mjs';
import { generate } from '../../lib/pipeline.mjs';
import { OUTPUTS, DENSITY_BANDS, GENERATED_MARK } from '../../style-dictionary.config.mjs';

const m = (entries) => new Map(entries.map(([p, value, type]) => [p, { value, type }]));

const light = m([
  ['antd.colorPrimary', '#2A62F0', 'color'],
  ['antd.fontSize', '14px', 'dimension'],
  ['antd.fontFamily', ['Be Vietnam Pro', 'sans-serif'], 'fontFamily'],
  ['math.font-scale', 1, 'number'],
]);
const dark = new Map(light).set('antd.colorPrimary', { value: '#3567EB', type: 'color' });
const compact = new Map(light).set('antd.fontSize', { value: '13px', type: 'dimension' });
const variants = new Map([['color.subject.math', { light: '#2563EB', dark: '#60A5FA', game: '#3D7BFF' }]]);

test('css-vars snapshot', () => {
  assert.equal(formatCssVars({ light, dark, compact }, '9.9.9'), `/* ${GENERATED_MARK}. Source: design/shared-tokens, design/admin-tokens (tokens@9.9.9). Run make design-tokens. */

:root {
  --ew-antd-color-primary: #2A62F0;
  --ew-antd-font-family: "Be Vietnam Pro", sans-serif;
  --ew-antd-font-size: 14px;
  --ew-math-font-scale: 1;
}

[data-theme="dark"] {
  --ew-antd-color-primary: #3567EB;
}

[data-density="compact"] {
  --ew-antd-font-size: 13px;
}
`);
});

test('antd-theme snapshot (light part, compactOverrides, domainColors)', () => {
  const ts = formatAntdTheme({ light, dark, compact }, variants, '9.9.9');
  assert.ok(ts.startsWith(`// ${GENERATED_MARK}`));
  assert.ok(ts.includes(`export const lightTheme: ThemeConfig = {
  algorithm: theme.defaultAlgorithm,
  token: {
    colorPrimary: "#2A62F0",
    fontFamily: "'Be Vietnam Pro', sans-serif",
    fontSize: 14
  },
};`));
  assert.ok(ts.includes('algorithm: theme.darkAlgorithm'));
  assert.ok(ts.includes(`export const compactOverrides: NonNullable<ThemeConfig['token']> = {
  fontSize: 13
};`));
  assert.ok(ts.includes(`"color.subject.math": {
    light: "#2563EB",
    dark: "#60A5FA"
  }`));
  assert.doesNotMatch(ts, /math\.font-scale/); // only antd.* seeds go to ThemeConfig
});

test('gdscript constants per type', () => {
  assert.equal(gdConst('size.space.16', { value: '16px', type: 'dimension' }), 'const SIZE_SPACE_16: int = 16');
  assert.equal(gdConst('motion.press', { value: '120ms', type: 'duration' }), 'const MOTION_PRESS: float = 0.12');
  assert.equal(gdConst('text.expansion_allowance', { value: 1.35, type: 'number' }), 'const TEXT_EXPANSION_ALLOWANCE: float = 1.35');
  assert.equal(gdConst('toon.steps', { value: 3, type: 'number' }), 'const TOON_STEPS: float = 3.0');
  assert.equal(gdConst('color.text.primary', { value: '#FFFFFF', type: 'color' }), 'const COLOR_TEXT_PRIMARY: Color = Color(1, 1, 1, 1)');
  assert.equal(gdConst('font.family.body', { value: ['x'], type: 'fontFamily' }), null);
});

test('godot-json is valid JSON keyed by context', () => {
  const j = JSON.parse(formatGodotJson({ game: light }, '9.9.9'));
  assert.equal(j.version, '9.9.9');
  assert.deepEqual(j.contexts.game['antd.fontSize'], { type: 'dimension', value: '14px' });
});

/** Minimal structural validation of a Godot text resource. */
function parseTres(text) {
  const lines = text.split('\n');
  assert.match(lines[0], /^; GENERATED by design\//);
  const head = /^\[gd_resource type="(\w+)"(?: load_steps=(\d+))? format=3\]$/.exec(lines[1]);
  assert.ok(head, `bad header: ${lines[1]}`);
  const ext = [...text.matchAll(/^\[ext_resource type="(\w+)" path="(res:\/\/[^"]+)" id="([^"]+)"\]$/gm)].map((x) => x[3]);
  const sub = [...text.matchAll(/^\[sub_resource type="(\w+)" id="([^"]+)"\]$/gm)].map((x) => x[2]);
  const steps = head[2] ? Number(head[2]) : 1;
  assert.equal(steps, ext.length + sub.length + 1, 'load_steps');
  for (const r of text.matchAll(/SubResource\("([^"]+)"\)/g)) assert.ok(sub.includes(r[1]), `undefined SubResource ${r[1]}`);
  for (const r of text.matchAll(/ExtResource\("([^"]+)"\)/g)) assert.ok(ext.includes(r[1]), `undefined ExtResource ${r[1]}`);
  const body = text.slice(text.indexOf('[resource]'));
  for (const line of body.split('\n').slice(1).filter(Boolean)) {
    assert.match(line, /^[A-Za-z_][\w/]* = (Color\([\d., ]+\)|-?\d+(\.\d+)?|true|false|&"\w+"|"[^"]*"|SubResource\("[^"]+"\)|ExtResource\("[^"]+"\)|Packed(Float32|Color)Array\([\d., ]*\))$/, line);
  }
  return { type: head[1], ext, sub, body };
}

test('pipeline produces every output with a GENERATED first line', async () => {
  const { files } = await generate();
  const expected = [
    OUTPUTS.antdTheme,
    OUTPUTS.tokensCss,
    OUTPUTS.uiTokens,
    `${OUTPUTS.godotThemeDir}/eduworld_theme.tres`,
    ...DENSITY_BANDS.map((b) => `${OUTPUTS.godotThemeDir}/eduworld_theme_${b}.tres`),
    `${OUTPUTS.godotThemeDir}/eduworld_theme_high_contrast.tres`,
    `${OUTPUTS.artDir}/art3d_tokens.gd`,
    `${OUTPUTS.artDir}/env_math.tres`,
    `${OUTPUTS.artDir}/vfx_reward_gradient.tres`,
  ];
  for (const rel of expected) {
    assert.ok(files.has(rel), rel);
    assert.ok(String(files.get(rel)).split('\n')[0].includes(GENERATED_MARK), rel);
  }
});

test('Godot Theme per density is a well-formed text resource with the band font size', async () => {
  const { files, resolved } = await generate();
  for (const band of DENSITY_BANDS) {
    const t = parseTres(files.get(`${OUTPUTS.godotThemeDir}/eduworld_theme_${band}.tres`));
    assert.equal(t.type, 'Theme');
    const base = Number(resolved.game.get(`density.${band}.font.base`).value.replace('px', ''));
    assert.ok(t.body.includes(`default_font_size = ${base}\n`), band);
    assert.ok(t.body.includes(`Button/font_sizes/font_size = ${base}\n`), band);
  }
  const hc = parseTres(files.get(`${OUTPUTS.godotThemeDir}/eduworld_theme_high_contrast.tres`));
  assert.ok(hc.body.includes('Label/colors/font_color = Color(0, 0, 0, 1)'));
  for (const [rel, content] of files) {
    if (rel.endsWith('.tres')) parseTres(content);
  }
});

test('UiTokens and Art3dTokens are typed GDScript classes', async () => {
  const { files } = await generate();
  const ui = files.get(OUTPUTS.uiTokens);
  assert.match(ui, /^class_name UiTokens$/m);
  assert.match(ui, /^extends RefCounted$/m);
  for (const line of ui.split('\n').filter((l) => l.startsWith('const '))) {
    assert.match(line, /^const [A-Z][A-Z0-9_]*: (int|float|Color|String|Dictionary|Array\[String\]) = /, line);
  }
  assert.doesNotMatch(ui, /^const (ZONE|TOON|ENV|VFX|OUTLINE)_/m);
  const art = files.get(`${OUTPUTS.artDir}/art3d_tokens.gd`);
  assert.match(art, /^class_name Art3dTokens$/m);
  assert.match(art, /const TOON_STEPS: float = 3\.0/);
  assert.match(art, /"legendary": Color\(/);
  assert.equal(formatUiTokens.length, 3);
});
